mapper.update:
UPDATE  /* isry.couns.constt.chttmng.mapper.inqChacttListMapper.updateChacttMemo : 채팅내역 채팅메모저장 */
        AYB200  
SET   
        CHTT_MEMO_CN            =       #{CHTT_MEMO_CN}
WHERE   CHRO_NO                 =       #{CHRO_NO}

UPDATE  /* isry.couns.constt.chttmng.mapper.inqChacttListMapper.updateCrisisBoard : 채팅내역 위기유형등록 */
        AYA110  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
WHERE   1=1
    AND CHRO_NO                 =       #{CHRO_NO}

UPDATE  /* isry.couns.constt.chttmng.mapper.inqChacttListMapper.updateCrisisPerson : 채팅내역 위기유형등록 */
        AYA120  
SET
        CRISIS_TYPE_SE_CD       =       #{CRISIS_TYPE_SE_CD} 
    ,   CLIENA_ID               =       #{CLIENA_ID}
    ,   LAST_MDFR_ID            =       #{LAST_MDFR_ID}
    ,   LAST_MDFCN_DT           =       SYSDATE
    ,   CONSTT_ID               =       #{CNSLTNT_ID}
WHERE   1=1
    AND CHRO_NO                 =       #{CHRO_NO}

UPDATE  /* isry.couns.constt.chttmng.mapper.inqChacttListMapper.updateCase : 채팅내역 슈퍼비전등록 */
        AYB200 
SET
        SUPV_SLCTN_CASE_YN      =       #{SUPV_SLCTN_CASE_YN}
WHERE   CHRO_NO                 =       #{CHRO_NO}
